static vector<int> parseRow(const string& s, size_t& p) {
    while (p < s.size() && (s[p] == ' ')) ++p;
    if (s[p++] != '[') throw runtime_error("bad input");
    vector<int> row;
    while (true) {
        while (p < s.size() && s[p] == ' ') ++p;
        if (s[p] == ']') { ++p; break; }
        int sign = 1;
        if (s[p] == '-') { sign = -1; ++p; }
        int v = 0; while (p < s.size() && isdigit((unsigned char)s[p])) v = v * 10 + (s[p++] - '0');
        row.push_back(sign * v);
        while (p < s.size() && s[p] == ' ') ++p;
        if (s[p] == ',') { ++p; continue; }
        if (s[p] == ']') { ++p; break; }
    }
    return row;
}

int main() {
    string line; getline(cin, line);
    size_t p = 0; while (p < line.size() && line[p] == ' ') ++p;
    if (line[p++] != '[' || line[p++] != '[') return 1;
    vector<vector<int>> matrix;
    while (true) {
        while (p < line.size() && (line[p] == ' ')) ++p;
        if (line[p] == ']') { ++p; break; }
