public class Main {
    private static final class Parser {
        private final String s;
        private int p = 0;
        Parser(String s) { this.s = s; }
        void ws() { while (p < s.length() && Character.isWhitespace(s.charAt(p))) p++; }
        void expect(char c) { ws(); if (p >= s.length() || s.charAt(p) != c) throw new IllegalArgumentException(); p++; }
        int nextInt() { ws(); int sign = 1; if (s.charAt(p) == '-') { sign = -1; p++; } int v = 0; while (p < s.length() && Character.isDigit(s.charAt(p))) v = v * 10 + (s.charAt(p++) - '0'); return sign * v; }
        int[][] readMatrixFromArgs() {
            expect('['); expect('[');
            List<int[]> rows = new ArrayList<>();
            ws();
            if (s.charAt(p) == ']') { p++; expect(']'); return new int[0][0]; }
            while (true) {
                expect('[');
                List<Integer> row = new ArrayList<>();
                ws();
                if (s.charAt(p) != ']') {
                    while (true) { row.add(nextInt()); ws(); if (s.charAt(p) == ',') { p++; continue; } break; }
                }
                expect(']');
                int[] a = new int[row.size()]; for (int i = 0; i < row.size(); i++) a[i] = row.get(i); rows.add(a);
                ws();
                if (s.charAt(p) == ',') { p++; continue; }
                break;
            }
            expect(']'); expect(']');
            return rows.toArray(new int[0][]);
        }
    }
    public static void main(String[] args) throws Exception {
        String line = new BufferedReader(new InputStreamReader(System.in)).readLine();
        int[][] matrix = new Parser(line).readMatrixFromArgs();
        System.out.println(new Solution().isToeplitzMatrix(matrix));
    }
}

